{"language":"js","summary":"Survey repo layout to split audit work","code":"const r = await Promise.all([
  Bun.$`pwd && git rev-parse --show-toplevel && git ls-files | wc -l`.text(),
  Bun.$`git ls-files | sed -E 's/\.[^./]+$//;t;d' | head -0; git ls-files | awk -F. 'NF>1{print $NF}' | sort | uniq -c | sort -rn | head -15`.text(),
  Bun.$`git ls-files | awk -F/ '{print $1"/"$2}' | sort | uniq -c | sort -rn | head -40`.text(),
  Bun.$`ls`.text(),
]);
print(r.join('\n---\n'));"}
